const grafana = new maple.ApiKey("grafana", {
    name: "grafana-readonly",
    scopes: [
        "dashboards:read",
        "traces:read",
        "metrics:read",
    ],
    rotate: quarterly.id,
});
export const grafanaKey = grafana.secret;
